<script setup lang="ts">
import {ref,watch} from 'vue';
import {NAlert,NButton,NCollapse,NCollapseItem,NFormItem,NInput,NInputNumber,NSelect,NSwitch} from 'naive-ui';
import {Plus,Trash2} from '@lucide/vue';
import type {Attribute,EntityInput} from '../studio-api';
const props=defineProps<{value:EntityInput;disabled?:boolean;template?:boolean}>();
const emit=defineEmits<{invalid:[value:boolean]}>();
const expanded=ref<string[]>([]),jsonErrors=ref<Record<number,string>>({});
const visibility=[{label:'公开',value:2},{label:'仅角色自己',value:1},{label:'仅 GM / 系统',value:0}];
const types=[{label:'文字',value:'str'},{label:'整数',value:'int'},{label:'小数',value:'float'},{label:'开关',value:'bool'},{label:'列表',value:'list'}];
function addDescription(){props.value.description.push({name:'',value:[],visibility:2});expanded.value.push('d'+(props.value.description.length-1))}
function addAttribute(){props.value.special_attributes.push({key:'',value_type:'str',current_value:'',why:'',how:'',when:'',visibility:2});expanded.value.push('a'+(props.value.special_attributes.length-1))}
function changeType(a:Attribute,type:Attribute['value_type']){a.value_type=type;a.current_value=type==='str'?'':type==='list'?[]:type==='bool'?false:0}
function jsonValue(a:Attribute,index:number,value:string){try{const parsed=JSON.parse(value);if(!Array.isArray(parsed))throw new Error();a.current_value=parsed;delete jsonErrors.value[index]}catch{jsonErrors.value[index]='请填写列表，例如 ["线索一", "线索二"]'}}
watch(()=>[props.value.name,...props.value.description.map(d=>d.name),...props.value.special_attributes.map(a=>a.key),Object.keys(jsonErrors.value).length],()=>emit('invalid',!props.value.name.trim()||props.value.description.some(d=>!d.name.trim())||props.value.special_attributes.some(a=>!a.key.trim())||Object.keys(jsonErrors.value).length>0),{immediate:true,deep:true});
</script>
<template><div class="entity-editor">
 <div class="form-grid"><NFormItem :label="template?'默认名称':'名字'" required><NInput v-model:value="value.name" :disabled="disabled" placeholder="给实体起个名字" :input-props="{'aria-label':template?'默认名称':'实体名字'}"/></NFormItem><NFormItem label="实体类型"><NInput v-model:value="value.type" :disabled="disabled" placeholder="human / world / location…" :input-props="{'aria-label':'实体类型'}"/></NFormItem></div>
 <div class="editor-section-heading"><div><h3>描述</h3><p>背景、外貌、规则等文字资料</p></div><NButton secondary size="small" :disabled="disabled" @click="addDescription"><template #icon><Plus :size="15"/></template>添加描述</NButton></div>
 <NCollapse v-model:expanded-names="expanded" class="field-collapse">
  <NCollapseItem v-for="(d,i) in value.description" :key="'d'+i" :name="'d'+i" :title="d.name||'新描述'"><template #header-extra><span class="visibility-label">{{visibility.find(v=>v.value===d.visibility)?.label}}</span></template><div class="field-form"><NFormItem label="描述名称" required><NInput v-model:value="d.name" :disabled="disabled" placeholder="例如：背景经历" :input-props="{'aria-label':'描述名称'}"/></NFormItem><NFormItem label="内容"><NInput :value="d.value.join('\n')" @update:value="d.value=$event.split('\n')" type="textarea" :autosize="{minRows:2,maxRows:7}" :disabled="disabled" placeholder="每行一段，可以暂时留空" :input-props="{'aria-label':'描述内容'}"/></NFormItem><div class="field-form-bottom"><NSelect v-model:value="d.visibility" :options="visibility" :disabled="disabled" aria-label="描述可见性"/><NButton quaternary type="error" :disabled="disabled" @click="value.description.splice(i,1)"><template #icon><Trash2 :size="16"/></template>删除</NButton></div></div></NCollapseItem>
 </NCollapse><p v-if="!value.description.length" class="editor-empty">还没有描述，可自己添加，也可让 AI 在对话中补充。</p>
 <div class="editor-section-heading"><div><h3>变量</h3><p>需要跟踪和变化的状态</p></div><NButton secondary size="small" :disabled="disabled" @click="addAttribute"><template #icon><Plus :size="15"/></template>添加变量</NButton></div>
 <NCollapse v-model:expanded-names="expanded" class="field-collapse"><NCollapseItem v-for="(a,i) in value.special_attributes" :key="'a'+i" :name="'a'+i" :title="a.key||'新变量'"><template #header-extra><span class="field-value-preview">{{Array.isArray(a.current_value)?`${a.current_value.length} 项`:String(a.current_value)}}</span></template><div class="field-form"><div class="form-grid"><NFormItem label="变量名" required><NInput v-model:value="a.key" :disabled="disabled" placeholder="例如：信任程度" :input-props="{'aria-label':'变量名'}"/></NFormItem><NFormItem label="值类型"><NSelect :value="a.value_type" @update:value="changeType(a,$event)" :options="types" :disabled="disabled" aria-label="值类型"/></NFormItem></div><NFormItem :label="template?'初始值':'当前值'" :validation-status="jsonErrors[i]?'error':undefined" :feedback="jsonErrors[i]"><NSwitch v-if="a.value_type==='bool'" :value="Boolean(a.current_value)" @update:value="a.current_value=$event" :disabled="disabled" aria-label="当前值"/><NInputNumber v-else-if="a.value_type==='int'||a.value_type==='float'" :value="Number(a.current_value)" @update:value="a.current_value=$event??0" :precision="a.value_type==='int'?0:undefined" :disabled="disabled" :input-props="{'aria-label':'当前值'}"/><NInput v-else-if="a.value_type==='list'" :default-value="JSON.stringify(a.current_value)" @update:value="jsonValue(a,i,$event)" type="textarea" :autosize="{minRows:2,maxRows:5}" :disabled="disabled" :input-props="{'aria-label':'列表值'}"/><NInput v-else :value="String(a.current_value)" @update:value="a.current_value=$event" :disabled="disabled" :input-props="{'aria-label':'当前值'}"/></NFormItem><NFormItem label="为什么需要这个变量"><NInput v-model:value="a.why" :disabled="disabled"/></NFormItem><NFormItem label="如何体现在故事中"><NInput v-model:value="a.how" type="textarea" :autosize="{minRows:2,maxRows:5}" placeholder="例如：低信任时只回答必要问题，不主动提供线索" :disabled="disabled"/></NFormItem><NFormItem label="什么时候修改"><NInput v-model:value="a.when" type="textarea" :autosize="{minRows:2,maxRows:4}" :disabled="disabled"/></NFormItem><div class="field-form-bottom"><NSelect v-model:value="a.visibility" :options="visibility" :disabled="disabled" aria-label="变量可见性"/><NButton quaternary type="error" :disabled="disabled" @click="value.special_attributes.splice(i,1);delete jsonErrors[i]"><template #icon><Trash2 :size="16"/></template>删除</NButton></div></div></NCollapseItem></NCollapse>
 <p v-if="!value.special_attributes.length" class="editor-empty">变量可以是文字、数字、开关或列表。</p><NAlert v-if="Object.keys(jsonErrors).length" type="error" :show-icon="false">请先修正列表值再保存。</NAlert>
</div></template>
